return "    #获取课程信息\n    get_course_data 4600 {\n        request {\n            class_type 0 : integer\n        }\n        response {\n            .course {\n                id 0 : integer\n                lv 1 : integer\n            }\n            result 0 : integer\n            course_data 1 : *course\n        }\n    }\n\n    #升级课程\n    course_levelup 4601 {\n        request {\n            courseid 0 : integer\n        }\n        response {\n            result 0 : integer # 1 成功2 配置错误 3 不能同时升级多个副科 4 解锁条件不满足 5 已升到满级 6 升级物品不足\n            courseid 1 : integer\n            level 2 : integer\n            consumes 3 : *consumeids\n        }\n    }\n\n    #课程重置\n    course_reset 4602 {\n        request {\n            class_type 0 : integer\n            courseid 1 : integer #重置全部 传0\n        }\n        response {\n            result 0 : integer # 1 成功 2 该课程未升级 3 钻石不足 4 需要先重置后置课程\n            costdiamond 1 : integer\n            level 2 : integer #消耗钻石\n            items 3 : *item  #获得物品\n        }\n    }\n"
